exercises.solution:
import statistics


def quartiles(valeurs):
    return statistics.quantiles(valeurs, n=4, method="inclusive")

import statistics


def cinq_valeurs(valeurs):
    q1, q2, q3 = statistics.quantiles(valeurs, n=4, method="inclusive")
    return {"min": min(valeurs), "q1": q1, "mediane": q2, "q3": q3, "max": max(valeurs)}
